# Pattern heavy version for two options that never change
class ShippingStrategy:
    def calculate(self, amount):
        raise NotImplementedError


class StandardShippingStrategy(ShippingStrategy):
    def calculate(self, amount):
        return 0 if amount > 50 else 5


class ExpressShippingStrategy(ShippingStrategy):
    def calculate(self, amount):
        return 15


class ShippingContext:
    def __init__(self, strategy):
        self.strategy = strategy

    def cost(self, amount):
        return self.strategy.calculate(amount)


if __name__ == "__main__":
    context = ShippingContext(StandardShippingStrategy())
    print(context.cost(60))

