// Pattern heavy version for two options that never change
interface ShippingStrategy {
    double calculate(double amount);
}

class StandardShippingStrategy implements ShippingStrategy {
    public double calculate(double amount) { return amount > 50 ? 0 : 5; }
}

class ExpressShippingStrategy implements ShippingStrategy {
    public double calculate(double amount) { return 15; }
}

class ShippingContext {
    private final ShippingStrategy strategy;
    ShippingContext(ShippingStrategy strategy) { this.strategy = strategy; }
    double cost(double amount) { return strategy.calculate(amount); }
}

public class Main {
    public static void main(String[] args) {
        ShippingContext context = new ShippingContext(new StandardShippingStrategy());
        System.out.println(context.cost(60));
    }
}

codes.cpp:
#include <iostream>
#include <memory>

class ShippingStrategy {
public:
    virtual double calculate(double amount) const = 0;
    virtual ~ShippingStrategy() = default;
};

class StandardShippingStrategy : public ShippingStrategy {
public:
    double calculate(double amount) const override { return amount > 50 ? 0 : 5; }
};

class ExpressShippingStrategy : public ShippingStrategy {
public:
    double calculate(double amount) const override { return 15; }
};

class ShippingContext {
    std::unique_ptr<ShippingStrategy> strategy;
public:
    explicit ShippingContext(std::unique_ptr<ShippingStrategy> strategy) : strategy(std::move(strategy)) {}
    double cost(double amount) const { return strategy->calculate(amount); }
};

int main() {
    ShippingContext context(std::make_unique<StandardShippingStrategy>());
    std::cout << context.cost(60) << std::endl;
    return 0;
}

