#include <iostream>
#include <string>

// Pattern heavy version for a class with one constructor
class Invoice {
public:
    std::string id;
    double amount;
    Invoice(std::string id, double amount) : id(std::move(id)), amount(amount) {}
};

class InvoiceFactory {
public:
    static Invoice create(const std::string& id, double amount) {
        return Invoice(id, amount);
    }
};

int main() {
    Invoice invoice = InvoiceFactory::create("INV-1", 200);
    std::cout << "Created invoice " << invoice.id << " for " << invoice.amount << std::endl;
    return 0;
}

